  1507  /*!
  1508   * Copy a layer into an image, taking account of the manifold modes. The
  1509   * contents of the image are replaced.
  1510   * \param xcf_image contains the layer and image to be replaced.
  1511   */
  1512  void XCFImageFormat::copyLayerToImage(XCFImage &xcf_image)
  1513  {
  1514      Layer &layer(xcf_image.layer);
  1515      QImage &image(xcf_image.image);
  1516      PixelCopyOperation copy = nullptr;
  1517
  1518      switch (layer.type) {
  1519      case RGB_GIMAGE:
  1520      case RGBA_GIMAGE:
  1521          copy = copyRGBToRGB;
  1522          break;
  1523      case GRAY_GIMAGE:
  1524          if (layer.opacity == OPAQUE_OPACITY) {
  1525              copy = copyGrayToGray;
  1526          } else {
  1527              copy = copyGrayToRGB;
  1528          }
  1529          break;
  1530      case GRAYA_GIMAGE:
  1531          copy = copyGrayAToRGB;
  1532          break;
  1533      case INDEXED_GIMAGE:
  1534          copy = copyIndexedToIndexed;
  1535          break;
  1536      case INDEXEDA_GIMAGE:
  1537          if (xcf_image.image.depth() <= 8) {
  1538              copy = copyIndexedAToIndexed;
  1539          } else {
  1540              copy = copyIndexedAToRGB;
  1541          }
  1542      }
  1543
  1544      if (!copy) {
  1545          return;
  1546      }
  1547
  1548      // For each tile...
  1549
  1550      for (uint j = 0; j < layer.nrows; j++) {
  1551          uint y = j * TILE_HEIGHT;
  1552
  1553          for (uint i = 0; i < layer.ncols; i++) {
  1554              uint x = i * TILE_WIDTH;
  1555
  1556              // This seems the best place to apply the dissolve because it
  1557              // depends on the global position of each tile's
  1558              // pixels. Apparently it's the only mode which can apply to a
  1559              // single layer.
  1560
  1561              if (layer.mode == DISSOLVE_MODE) {
  1562                  if (!random_table_initialized) {
  1563                      initializeRandomTable();
  1564                      random_table_initialized = true;
  1565                  }
  1566                  if (layer.type == RGBA_GIMAGE) {
  1567                      dissolveRGBPixels(layer.image_tiles[j][i], x, y);
  1568                  }
  1569
  1570                  else if (layer.type == GRAYA_GIMAGE) {
  1571                      dissolveAlphaPixels(layer.alpha_tiles[j][i], x, y);
  1572                  }
  1573              }
  1574
  1575              // Shortcut for common case
  1576              if (copy == copyRGBToRGB && layer.apply_mask != 1) {
  1577                  QPainter painter(&image);
  1578                  painter.setOpacity(layer.opacity / 255.0);
  1579                  painter.setCompositionMode(QPainter::CompositionMode_Source);
  1580                  painter.drawImage(x + layer.x_offset, y + layer.y_offset, layer.image_tiles[j][i]);
  1581                  continue;
  1582              }
  1583
  1584              for (int l = 0; l < layer.image_tiles[j][i].height(); l++) {
  1585                  for (int k = 0; k < layer.image_tiles[j][i].width(); k++) {
  1586
  1587                      int m = x + k + layer.x_offset;
  1588                      int n = y + l + layer.y_offset;
  1589
  1590                      if (m < 0 || m >= image.width() || n < 0 || n >= image.height()) {
  1591                          continue;
  1592                      }
  1593
  1594                      (*copy)(layer, i, j, k, l, image, m, n);
  1595                  }
  1596              }
  1597          }
  1598      }
  1599  }
